(()=>{const el=document.querySelector('#calculationFeed');let n=0;const codes=['CALC Δt = Σ(branch.offset)','MAP ψ[626] → anchor.matrix','SOLVE nexus.crossing(window)','VERIFY identity ≠ origin.copy','WARNING: temporal shear > limit','RECALCULATE λ / phase.offset','SCAN incoming.variant.signature','CHECK prime.human // ACCEPTED','ESTIMATE arrival.time // PENDING','LOCK 2026-12-18 / TORINO'];function update(){const row=document.createElement('span');row.className=n%5===4?'cmd-warning':n%3===0?'cmd-lore':n%3===1?'cmd-calc':'cmd-ok';row.textContent='0x'+(626+n).toString(16).toUpperCase()+' > '+codes[n%codes.length]+'\n  '+(Math.sin(n*.17)*.626).toFixed(6)+' / CRC '+((n*7919)%65536).toString(16).padStart(4,'0')+'\n';el.append(row);while(el.children.length>8)el.firstChild.remove();el.scrollTop=el.scrollHeight;n++}setInterval(update,260);update()})();
(()=>{const canvas=document.querySelector('#stellarDebris'),g=canvas.getContext('2d');let w,h;function resize(){w=canvas.width=innerWidth;h=canvas.height=innerHeight}resize();addEventListener('resize',resize);const stars=Array.from({length:170},()=>({a:Math.random()*Math.PI*2,r:Math.random(),z:.25+Math.random()*.75,s:Math.random()*2+.5}));function frame(t){requestAnimationFrame(frame);g.clearRect(0,0,w,h);if(document.body.classList.contains('awaiting-init')||document.body.classList.contains('blackout')||document.body.classList.contains('rebooting'))return;const calm=matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('calm');g.globalCompositeOperation='screen';const cx=w*.5,cy=h*.35,scale=Math.min(w*.33,h*.44);for(const p of stars){const r=calm?p.r:((p.r+t*.000025*p.z)%1),xx=Math.cos(p.a)*r*scale,yy=Math.sin(p.a)*r*scale*.75;g.strokeStyle=p.z>.75?'rgba(255,185,130,'+(r*.55)+')':'rgba(115,193,255,'+(r*.7)+')';g.lineWidth=p.s*p.z;g.beginPath();g.moveTo(cx+xx,cy+yy);g.lineTo(cx+xx*(1-.035*p.z),cy+yy*(1-.035*p.z));g.stroke()}g.globalCompositeOperation='source-over'}requestAnimationFrame(frame)})();
(()=>{const c=document.querySelector('#labInstruments'),g=c.getContext('2d');let w,h;function resize(){w=c.width=innerWidth;h=c.height=innerHeight}resize();addEventListener('resize',resize);function frame(t){requestAnimationFrame(frame);g.clearRect(0,0,w,h);if(document.body.classList.contains('awaiting-init')||document.body.classList.contains('blackout'))return;const calm=matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('calm');if(calm)t=0;const left=w*.12,right=w*.88,base=h*.71;g.globalCompositeOperation='screen';for(let side of [-1,1]){let x=side<0?left:right;g.save();g.translate(x,base);g.strokeStyle='#4dc8ff66';g.lineWidth=1;g.scale(1,.35);for(let i=0;i<4;i++){g.beginPath();g.ellipse(0,0,35+i*10,35+i*10,0,0,Math.PI*2);g.stroke()}g.strokeStyle='#a0eaff';g.beginPath();g.arc(0,0,55,t*.0007*side,t*.0007*side+1.3);g.stroke();g.restore();for(let i=0;i<22;i++){let p=(i/22+t*.0001)%1,px=x+side*Math.sin(p*5)*25,py=base-p*h*.2;g.fillStyle='rgba(70,190,255,'+((1-p)*.55)+')';g.fillRect(px,py,2,2)}g.font='7px monospace';g.fillStyle='#7ddcffaa';g.fillText(side<0?'PLASMA ARRAY / 626':'SPECTRAL ANALYSER / LIVE',x-60,base+32)}for(let j=0;j<3;j++){g.beginPath();for(let i=0;i<=100;i++){let p=i/100,x=w*(.03+.94*p),y=h*(.79+j*.04)-Math.sin(p*Math.PI)*h*.1;g.strokeStyle='rgba(42,136,255,'+(.08+j*.02)+')';g.lineTo(x,y)}g.stroke();for(let k=0;k<4;k++){let p=(t*.00004+k*.25+j*.13)%1,x=w*(.03+.94*p),y=h*(.79+j*.04)-Math.sin(p*Math.PI)*h*.1;g.fillStyle='#8adeff88';g.fillRect(x,y,5,1)}}g.globalCompositeOperation='source-over'}requestAnimationFrame(frame)})();
